-- Independent clone. No source credentials or sessions.
PRAGMA defer_foreign_keys=ON;
CREATE TABLE analytics_daily (day TEXT PRIMARY KEY,views INTEGER NOT NULL DEFAULT 0,sessions INTEGER NOT NULL DEFAULT 0);
CREATE TABLE analytics_devices_daily (day TEXT NOT NULL,device TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,sessions INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,device));
CREATE TABLE analytics_events (
 id TEXT PRIMARY KEY, day TEXT NOT NULL, sid TEXT NOT NULL, at INTEGER NOT NULL,
 path TEXT NOT NULL, device TEXT NOT NULL, referrer TEXT NOT NULL
);
CREATE TABLE analytics_hourly (day TEXT NOT NULL,hour INTEGER NOT NULL,views INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,hour));
CREATE TABLE analytics_page_daily (day TEXT NOT NULL,path TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,path));
CREATE TABLE analytics_referrers_daily (day TEXT NOT NULL,host TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,sessions INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,host));
CREATE TABLE analytics_sessions (
 day TEXT NOT NULL, sid TEXT NOT NULL, device TEXT NOT NULL, referrer TEXT NOT NULL,
 first_seen INTEGER NOT NULL, last_seen INTEGER NOT NULL, views INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(day,sid)
);
CREATE TABLE file_chunks(file_id TEXT,part INTEGER,data BLOB,PRIMARY KEY(file_id,part));
CREATE TABLE files(id TEXT PRIMARY KEY,name TEXT,mime TEXT,size INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inquiries(id TEXT PRIMARY KEY,type TEXT NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,organization TEXT DEFAULT '',subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT DEFAULT 'new',consent_version TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pages(path TEXT PRIMARY KEY,title TEXT NOT NULL,html TEXT NOT NULL,images TEXT NOT NULL DEFAULT '[]',sort_order INTEGER DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts(id TEXT PRIMARY KEY,category TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,attachment_url TEXT DEFAULT '',image_url TEXT DEFAULT '',source_url TEXT DEFAULT '',published INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rate_limits(key TEXT,bucket INTEGER,count INTEGER,expires_at INTEGER,PRIMARY KEY(key,bucket));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/Home','포럼소개','<div class="original-layout original-home"><div class="original-row"><div class="original-col" data-original-span="2" style="flex:2 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="2" style="flex:2 1 0%"><span id="w20260514e2c5982d3ba57"></span></div></div><div class="original-row"><div class="original-col" data-original-span="2" style="flex:2 1 0%"><div id="w2026050431f43245b7d9e"><figure class="original-image"><img src="/assets/f22b923eb1bbe.png" alt="포럼소개" loading="lazy"></figure></div></div></div></div><div class="original-col" data-original-span="8" style="flex:8 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="8" style="flex:8 1 0%"><span id="w202605144c58ae8167e23"></span></div></div><div class="original-row"><div class="original-col" data-original-span="8" style="flex:8 1 0%"><div id="w20260504a9520e9b69182"><section class="original-text"><div><div style="padding:31px 20px;padding-top:31px;padding-right:20px;padding-bottom:31px;padding-left:20px;border-left:4px solid rgb(47, 143, 91);border-radius:4px;box-sizing:border-box;line-height:1.7;font-size:18px;color:rgb(31, 41, 51);background:rgb(238, 248, 243);background-color:rgb(238, 248, 243)"><p style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-weight:700;color:rgb(31, 79, 122)">정원은 생명이고, 도시의 미래입니다.</p><p style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px">우리는 정원을 통해 탄소중립과 ESG를 실천하며</p><p style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">시민과 함께 지속가능한 도시 생태문화를 만들어갑니다.</p></div></div></section></div></div></div><div class="original-row"><div class="original-col" data-original-span="8" style="flex:8 1 0%"><div id="w20260504d29a26063ca08"><section class="original-text"><div><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">대한민국은 기후변화 심화, 탄소중립 이행 지연, 도시의 생태 단절과 열섬현상 악화, 공동체의 약화와 시민 삶의 질 저하라는 복합적 위기에 직면해 있습니다.</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">이러한 국가적 문제는 단순한 기술이나 경제적 조치만으로 해결할 수 없습니다. 자연과 인간, 사회를 동시에 회복하는 종합적 접근이 필수적입니다. 정원은 탄소를 흡수하고, 생태계를 복원하며, 도시 열섬을 완화하고, 시민의 정신적·육체적 건강을 증진하는 자연기반 해법(Nature-based Solution, NbS) 입니다.</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)"><br></span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">"정원정책"은 이제 단순한 조경사업이 아니라 국가 차원의 지속가능성 전략이 되어야 합니다. 정원은 기업과 지자체가 ESG를 실천하는 강력한 도구가 될 수 있습니다.</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">기업은 정원을 통해 환경(E) 기여, 사회적 책임(S) 수행, 투명한 거버넌스(G) 모델을 구축할 수 있습니다</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">지방정부는 정원을 통해 탄소중립 도시, 건강한 커뮤니티를 조성할 수 있습니다. 국민과 시민은 정원을 매개로 삶의 질을 높이고, 공동체를 회복할 수 있습니다.</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)"><br></span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">정원문화의 보급과 확산은 곧 기후위기에 대응하는 시민 행동을 이끌고, 지역경제를 활성화하며, ESG경영을 넘어선 ESG사회를 구현하는 첫걸음이 될 것입니다. 따라서 대한민국 ESG 정원정책 포럼은 국가 차원의 정원정책 비전과 로드맵 제시, 기업과 지자체의 ESG 실천모델로서 정원사업 확산 제안, 시민 참여형 정원문화 확산을 위한 정책 개발과 캠페인 추진, 글로벌 ESG 트렌드에 부합하는 대한민국형 정원정책 모델 수립과 법·제도 개선을 위한 국회, 정부, 지방정부, 민간의 연대체 구축등의 사업 비전을 공유해 나갈 것입니다.</span></p><p style="text-align:justify"><span style="color:rgb(0, 0, 0)">「대한민국 ESG 정원정책포럼」은 정원을 통해 국가적 문제를 해결하고,기업과 지자체, 시민 모두가 ESG를 생활 속에서 실천하는 새로운 시대를 열어가고자 합니다. 이 거대한 녹색 전환(Green Transformation) 운동에 &nbsp;여러분과 함께 힘차게 펼쳐 나가고자 &nbsp;합니다.</span></p></div></section></div></div></div><div class="original-row"><div class="original-col" data-original-span="8" style="flex:8 1 0%"><div id="w20260504beea698054c5d"><section class="original-text"><div><p style="text-align:right"><span style="color:rgb(0, 0, 0)">발기인 대표, 이사장 곽 상 욱</span></p><p style="text-align:right"><span style="color:rgb(0, 0, 0)">前 오산시장</span></p></div></section></div></div></div></div></div></div>','[{"src":"/assets/f22b923eb1bbe.png","alt":"포럼소개"}]',0,'2026-11-10 06:42:10');
