INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/members','함께 하는 분들','<div class="original-layout original-members"><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w20260514a0538a3367626"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w202605058e30da0fc027c"><section class="original-text" id="original-founders"><div><div style="display:flex;width:100%;padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border-bottom:1px solid rgb(47, 143, 91);box-sizing:border-box"><a href="#original-founders" style="display:block;width:50%;padding:13px 10px 14px;padding-top:13px;padding-right:10px;padding-bottom:14px;padding-left:10px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border-top:1px solid rgb(47, 143, 91);border-right:1px solid rgb(47, 143, 91);border-left:1px solid rgb(47, 143, 91);border-radius:10px 10px 0px 0px;box-sizing:border-box;text-align:center;line-height:1.4;font-size:18px;font-weight:700;color:rgb(255, 255, 255);background:rgb(47, 143, 91);background-color:rgb(47, 143, 91)" rel="noopener noreferrer">&nbsp;설립 발기인&nbsp;</a> <a href="#original-officers" style="display:block;width:50%;padding:13px 10px 14px;padding-top:13px;padding-right:10px;padding-bottom:14px;padding-left:10px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border-top:1px solid rgb(221, 221, 221);border-right:1px solid rgb(221, 221, 221);border-radius:10px 10px 0px 0px;box-sizing:border-box;text-align:center;line-height:1.4;font-size:18px;font-weight:600;color:rgb(119, 119, 119);background:rgb(245, 245, 245);background-color:rgb(245, 245, 2