INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/mediaroom','미디어룸','<div class="original-layout original-mediaroom"><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w20260514ecba9129e760b"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260504fa47133179084"><section class="original-text"><div><div style="padding:28px 30px;padding-top:28px;padding-right:30px;padding-bottom:28px;padding-left:30px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border:1px solid rgb(209, 213, 219);border-top:1px solid rgb(209, 213, 219);border-right:1px solid rgb(209, 213, 219);border-bottom:1px solid rgb(209, 213, 219);border-left:1px solid rgb(209, 213, 219);border-radius:10px;box-sizing:border-box;line-height:1.75;color:rgb(17, 24, 39);background:rgb(255, 255, 255);background-color:rgb(255, 255, 255)"><div style="margin:0px 0px 14px;margin-top:0px;margin-right:0px;margin-bottom:14px;margin-left:0px;line-height:1.6;font-size:20px;font-weight:700;color:rgb(17, 24, 39)">대한민국ESG정원정책포럼의 다양한 활동과 인사이트를 영상으로 전합니다.</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;line-height:1.75;font-size:16px;color:rgb(75, 85, 99)">정원정책, ESG 실천, 기업·지자체 협력 사례까지<br>현장에서 만들어지는 변화를 직접 확인할 수 있습니다.</div></div></div></section></div></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260504b44dbce1e1460"><section class="original-text"><div><div style="display:flex;align-items:center;gap:18px;row-gap:18px;column-gap:18px;max-width:760px;padding:20px 0px;padding-top:20px;padding-right:0px;padding-bottom:20px;padding-left:0px;box-sizing:border-box;line-height:1.7;color:rgb(17, 24, 39);background:rgb(255, 255, 255);background-color:rgb(255, 255, 255)"><div style="flex:0 0 auto;flex-grow:0;flex-shrink:0;flex-basis:auto"><img src="/assets/e00f5aa178820.png" loading="lazy" alt="기존 홈페이지 이미지"></div><div style="font-size:16px;color:rgb(55, 65, 81)"><span style="font-weight:700;color:rgb(17, 24, 39)">라이브 방송 상태</span> : <span style="font-weight:700;color:rgb(220, 38, 38)">지금은 방송 시간이 아닙니다.</span></div></div></div></section></div></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260521d7e94153464b4"><section class="original-text"><div><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">미디어룸</div></div></section></div></div></div><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w20260521d2a225b1d29a5"></span></div></div></div></div></div><div class="original-media-grid"><figure><img loading="lazy" src="/assets/4ee1fdb6ec47f.jpg" alt="기존 미디어룸 이미지"><figcaption>라이브 방송 상태 : 지금은 방송 시간이 아닙니다.</figcaption></figure><a href="https://www.youtube.com/watch?v=YqUhYalOH5Y" target="_blank" rel="noopener noreferrer"><figure><img loading="lazy" src="/assets/c6c7e242ddd1a.jpg" alt="혁신리더십 연수(천리포수목원)"><figcaption>혁신리더십 연수(천리포수목원) 영상 보기 ↗</figcaption></figure></a></div>','[{"src":"/assets/e00f5aa178820.png","alt":"기존 홈페이지 이미지"}]',20,'2026-11-10 06:42:18');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/memberndonation','회원 및 후원','<div class="original-layout original-memberndonation"><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w202605144df2bdb1e6770"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260505ee699935e82ed"><section class="original-text"><div><div style="padding:28px 30px;padding-top:28px;padding-right:30px;padding-bottom:28px;padding-left:30px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border:1px solid rgb(209, 213, 219);border-top:1px solid rgb(209, 213, 219);border-right:1px solid rgb(209, 213, 219);border-bottom:1px solid rgb(209, 213, 219);border-left:1px solid rgb(209, 213, 219);border-radius:10px;box-sizing:border-box;line-height:1.75;color:rgb(17, 24, 39);background:rgb(255, 255, 255);background-color:rgb(255, 255, 255)"><div style="margin:0px 0px 14px;margin-top:0px;margin-right:0px;margin-bottom:14px;margin-left:0px;line-height:1.6;font-size:20px;font-weight:700;color:rgb(17, 24, 39)">ESG정원정책포럼은 기업, 공공기관, 전문가, 시민이 함께 참여하는 협력 기반 네트워크입니다.</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;line-height:1.75;font-size:16px;color:rgb(75, 85, 99)">회원으로 참여하시면 정원정책과 ESG 실천을 연결하는 다양한 활동에 함께할 수 있습니다.</div></div></div></section></div></div></div><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w202605054c75bf86400c3"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w202605055a363c2a0cf5f"><section class="original-text"><div><div style="box-sizing:border-box;line-height:1.7;font-size:15px;color:rgb(17, 24, 39)"><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 24px;margin-top:0px;margin-right:0px;margin-bottom:24px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">회원 유형</div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">01</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">기관회원 <span style="font-size:14px;font-weight:500;color:rgb(107, 114, 128)">(기업·지자체·공공기관)</span></div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">기업, 지방자치단체, 공공기관, 유관 단체</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">ESG 실천 및 정책 협력 중심</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">기업정원 및 지역 프로젝트 참여</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">기관 단위 협력 프로그램 운영</li></ul></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">02</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">개인회원 <span style="font-size:14px;font-weight:500;color:rgb(107, 114, 128)">(전문가·일반)</span></div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">중앙 및 지방정부 공무원, 연구자, 실무자, 학생, 시민 등</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">정책·연구·교육 참여</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">네트워킹 및 커뮤니티 활동</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">정원문화 확산 활동 참여</li></ul></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">03</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">후원회원</div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">포럼의 활동과 가치에 공감하여 재정적으로 후원하는 개인·기관</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">기부 및 후원을 통한 참여</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">공익사업 지원</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">주요 활동 소식 공유</li></ul><p><br></p></div></div></div></div><p><br></p><div style="box-sizing:border-box;line-height:1.7;font-size:15px;color:rgb(17, 24, 39)"><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 24px;margin-top:0px;margin-right:0px;margin-bottom:24px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">가입절차</div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">01</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">가입 신청서 작성</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">회원 유형에 맞는 가입 신청서를 작성합니다.</div></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">02</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">회비 또는 후원금 납부</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">회원 유형별로 정해진 계좌로 회비 또는 후원금을 납부합니다.</div></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 32px;margin-top:0px;margin-right:0px;margin-bottom:32px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">03</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">사무국 확인 및 회원 등록</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">사무국에서 신청서와 납부 내역을 확인합니다.<br>필요 시 회비납부 확인서 또는 후원금 납부 확인서를 발급합니다.</div><p><br></p><p><br></p></div></div></div><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 18px;margin-top:0px;margin-right:0px;margin-bottom:18px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">문의</div><div style="padding:20px 22px;padding-top:20px;padding-right:22px;padding-bottom:20px;padding-left:22px;border-left:4px solid rgb(47, 143, 91);border-radius:4px;box-sizing:border-box;background:rgb(238, 248, 243);background-color:rgb(238, 248, 243)"><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">회원제도 및 가입 관련 문의는 사무국으로 연락주시기 바랍니다.</div><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;color:rgb(17, 24, 39)"><strong style="color:rgb(31, 79, 122)">이메일</strong> : <a href="mailto:esg.gardenpolicy@gmail.com" style="color:rgb(47, 143, 91)" rel="noopener noreferrer">&nbsp;esg.gardenpolicy@gmail.com&nbsp;</a></div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(17, 24, 39)"><strong style="color:rgb(31, 79, 122)">연회비 납부계좌</strong> : 농협 351-1367-9439-73 사단법인 ESG정원정책포럼</div></div></div></div></section></div></div></div></div></div></div>','[]',21,'2026-11-10 06:42:18');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/membership','회원제도안내','<div class="original-layout original-membership"><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w202605144df2bdb1e6770"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260505ee699935e82ed"><section class="original-text"><div><div style="padding:28px 30px;padding-top:28px;padding-right:30px;padding-bottom:28px;padding-left:30px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;border:1px solid rgb(209, 213, 219);border-top:1px solid rgb(209, 213, 219);border-right:1px solid rgb(209, 213, 219);border-bottom:1px solid rgb(209, 213, 219);border-left:1px solid rgb(209, 213, 219);border-radius:10px;box-sizing:border-box;line-height:1.75;color:rgb(17, 24, 39);background:rgb(255, 255, 255);background-color:rgb(255, 255, 255)"><div style="margin:0px 0px 14px;margin-top:0px;margin-right:0px;margin-bottom:14px;margin-left:0px;line-height:1.6;font-size:20px;font-weight:700;color:rgb(17, 24, 39)">ESG정원정책포럼은 기업, 공공기관, 전문가, 시민이 함께 참여하는 협력 기반 네트워크입니다.</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;line-height:1.75;font-size:16px;color:rgb(75, 85, 99)">회원으로 참여하시면 정원정책과 ESG 실천을 연결하는 다양한 활동에 함께할 수 있습니다.</div></div></div></section></div></div></div><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w202605054c75bf86400c3"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w202605055a363c2a0cf5f"><section class="original-text"><div><div style="box-sizing:border-box;line-height:1.7;font-size:15px;color:rgb(17, 24, 39)"><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 24px;margin-top:0px;margin-right:0px;margin-bottom:24px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">회원 유형</div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">01</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">기관회원 <span style="font-size:14px;font-weight:500;color:rgb(107, 114, 128)">(기업·지자체·공공기관)</span></div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">기업, 지방자치단체, 공공기관, 유관 단체</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">ESG 실천 및 정책 협력 중심</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">기업정원 및 지역 프로젝트 참여</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">기관 단위 협력 프로그램 운영</li></ul></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">02</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">개인회원 <span style="font-size:14px;font-weight:500;color:rgb(107, 114, 128)">(전문가·일반)</span></div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">중앙 및 지방정부 공무원, 연구자, 실무자, 학생, 시민 등</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">정책·연구·교육 참여</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">네트워킹 및 커뮤니티 활동</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">정원문화 확산 활동 참여</li></ul></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">03</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">후원회원</div><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">포럼의 활동과 가치에 공감하여 재정적으로 후원하는 개인·기관</div><ul style="padding-left:20px;margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px"><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">기부 및 후원을 통한 참여</li><li style="margin:0px 0px 4px;margin-top:0px;margin-right:0px;margin-bottom:4px;margin-left:0px">공익사업 지원</li><li style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px">주요 활동 소식 공유</li></ul><p><br></p></div></div></div></div><p><br></p><div style="box-sizing:border-box;line-height:1.7;font-size:15px;color:rgb(17, 24, 39)"><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 24px;margin-top:0px;margin-right:0px;margin-bottom:24px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">가입절차</div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">01</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">가입 신청서 작성</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">회원 유형에 맞는 가입 신청서를 작성합니다.</div></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 28px;margin-top:0px;margin-right:0px;margin-bottom:28px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">02</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">회비 또는 후원금 납부</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">회원 유형별로 정해진 계좌로 회비 또는 후원금을 납부합니다.</div></div></div></div><div style="padding:0px;padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px;margin:0px 0px 32px;margin-top:0px;margin-right:0px;margin-bottom:32px;margin-left:0px;box-sizing:border-box"><div style="display:flex;align-items:flex-start;gap:14px;row-gap:14px;column-gap:14px"><div style="min-width:36px;line-height:1.3;font-size:20px;font-weight:700;color:rgb(47, 143, 91)">03</div><div style="flex:1 1 0%;flex-grow:1;flex-shrink:1;flex-basis:0%"><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;font-size:16px;font-weight:700;color:rgb(17, 24, 39)">사무국 확인 및 회원 등록</div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(55, 65, 81)">사무국에서 신청서와 납부 내역을 확인합니다.<br>필요 시 회비납부 확인서 또는 후원금 납부 확인서를 발급합니다.</div><p><br></p><p><br></p></div></div></div><div style="padding:0px 0px 12px;padding-top:0px;padding-right:0px;padding-bottom:12px;padding-left:0px;margin:0px 0px 18px;margin-top:0px;margin-right:0px;margin-bottom:18px;margin-left:0px;border-bottom:2px solid rgb(47, 143, 91);line-height:1.4;font-size:22px;font-weight:700;color:rgb(31, 79, 122)">문의</div><div style="padding:20px 22px;padding-top:20px;padding-right:22px;padding-bottom:20px;padding-left:22px;border-left:4px solid rgb(47, 143, 91);border-radius:4px;box-sizing:border-box;background:rgb(238, 248, 243);background-color:rgb(238, 248, 243)"><div style="margin:0px 0px 10px;margin-top:0px;margin-right:0px;margin-bottom:10px;margin-left:0px;color:rgb(55, 65, 81)">회원제도 및 가입 관련 문의는 사무국으로 연락주시기 바랍니다.</div><div style="margin:0px 0px 8px;margin-top:0px;margin-right:0px;margin-bottom:8px;margin-left:0px;color:rgb(17, 24, 39)"><strong style="color:rgb(31, 79, 122)">이메일</strong> : <a href="mailto:esg.gardenpolicy@gmail.com" style="color:rgb(47, 143, 91)" rel="noopener noreferrer">&nbsp;esg.gardenpolicy@gmail.com&nbsp;</a></div><div style="margin:0px;margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;color:rgb(17, 24, 39)"><strong style="color:rgb(31, 79, 122)">연회비 납부계좌</strong> : 농협 351-1367-9439-73 사단법인 ESG정원정책포럼</div></div></div></div></section></div></div></div></div></div></div>','[]',22,'2026-11-10 06:42:19');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/memberstatus','회원현항','<div class="original-layout original-memberstatus"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w20260518c9887a7c176e6"></span></div></div><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260508997d892bffc7a"><section class="original-text"><div></div></section></div></div></div></div></div></div>','[]',23,'2026-11-10 06:42:19');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/finance','재정보고','<div class="original-layout original-finance"><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div class="original-row original-anchor-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><span id="w20260518a3fb78d45df8c"></span></div></div><div class="original-row"><div class="original-col" data-original-span="10" style="flex:10 1 0%"><div id="w20260508183a3b54b91a7"><section class="original-text"><div><ul><li>ESG정원정책포럼은 투명한 운영과 공익적 가치 실현을 위해 재정 운영 현황을 단계적으로 공개해나갈 예정입니다.</li><li>현재 재정보고 시스템을 정비 중이며 보다 투명하고 체계적인 정보 공개를 위해 준비하고 있습니다.</li><li>포럼의 재정 운영 현황 및 연간 사업보고는 향후 순차적으로 공개될 예정입니다.</li></ul></div></section></div></div></div></div></div></div>','[]',24,'2026-11-10 06:42:19');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/terms','이용약관','<section class="content-block">이용약관<br>	<br>		<br>		닫기<br>	<br><br><br>	[이용약관]<br>제1장 총칙<br><br>제1조(목적)<br>이 약관은 사단법인 ESG정원정책포럼 (이하 &quot;본포럼&quot;라 합니다)가 인터넷서비스(이하 &quot;서비스&quot;라 합니다)를 제공함에 있어 가입조건 및 이용에 관한 제반 사항과 기타 필요한 사항을 구체적으로 규정함을 목적으로 합니다.<br><br>제2조(용어의 정의)<br>이 약관에서 사용하는 용어의 정의는 다음과 같습니다.<br>① &quot;서비스&quot;라 함은 구현되는 단말기(PC, TV, 휴대형단말기 등의 각종 유무선 장치를 포함)와 상관없이 이용할 수 있는 본포럼 홈페이지 관련 제반 서비스를 의미합니다.<br>② &quot;회원&quot;이라 함은 본포럼의 &quot;서비스&quot;에 접속하여 이 약관에 따라 &quot;본포럼&quot;와 이용계약을 체결하고 &quot;본포럼&quot;의 &quot;서비스&quot;를 이용하는 자를 말합니다.<br>③ &quot;아이디(ID)&quot;라 함은 &quot;회원&quot;의 식별과 &quot;서비스&quot; 이용을 위하여 &quot;회원&quot;이 정하고 &quot;본포럼&quot;가 승인하는 문자와 숫자의 조합을 의미합니다.<br>④ &quot;비밀번호&quot;라 함은 &quot;회원&quot;이 부여 받은 &quot;아이디와 일치되는 &quot;회원&quot;임을 확인하고 통신상의 비밀보호를 위해 &quot;회원&quot; 자신이 정한 문자와 숫자의 조합을 의미합니다.<br>⑤ &quot;게시물&quot;이라 함은 &quot;회원&quot;이 &quot;서비스&quot;를 이용함에 있어 &quot;서비스상&quot;에 게시한 부호ㆍ문자ㆍ음성ㆍ음향ㆍ화상ㆍ동영상 등의 정보 형태의 글, 사진, 동영상 및 각종 파일과 링크 등을 의미합니다.<br><br>제3조(약관의 유효 및 변경)<br>① 이 약관은 “본포럼” 홈페이지에 게시함으로써 유효합니다.<br>② 본포럼은 &quot;본포럼&quot;는 &quot;약관의 규제에 관한 법률&quot;,&quot;정보통신망 이용촉진 및 정보보호 등에 관한 법률(이하 &quot;정보통신망법&quot;)&quot; 등 관련법이 허용하는 범위에서 이 약관을 변경할 수 있으며, 변경된 약관은 제1항과 같은 방법으로 게시함으로써 유효하게 됩니다.<br>③ &quot;본포럼&quot;가 약관을 개정할 경우에는 적용일자 및 개정사유를 명시하여 현행약관과 함께 제1항의 방식에 따라 그 개정약관의 적용일자 30일 전부터 적용일자 전일까지 공지합니다. 다만, 회원에게 불리한 약관의 개정의 경우에는 공지 외에 일정기간 서비스 내 전자우편, 로그인시 동의 창 등의 전자적 수단을 통해 따로 명확히 통지하도록 합니다.<br>④ &quot;본포럼&quot;가 전항에 따라 개정약관을 공지 또는 통지하면서 &quot;회원&quot;에게 30일 기간 내에 의사표시를 하지 않으면 의사표시가 표명된 것으로 본다는 뜻을 명확하게 공지 또는 통지하였음에도 &quot;회원&quot;이 명시적으로 거부의 의사표시를 하지 아니한 경우 &quot;회원&quot;이 개정약관에 동의한 것으로 봅니다.<br>⑤ “회원”은 변경된 약관에 동의하지 않으면 언제든지 “서비스” 이용을 중단하고 “서비스” 이용을 해지할 수 있습니다. 이 경우 “서비스” 이용의 해지는 본포럼에 “회원” 가입의 해지신청을 함으로써 해지됩니다.<br>⑥ 인터넷회원이 제2항에 규정된 변경약관에 대하여 약관의 시행일 이후 별도의 통지없이 계속적으로 서비스를 이용하는 경우 약관의 변경 사항에 동의한 것으로 간주합니다.<br><br>제4조(약관외 준용규정)<br>이 약관에 명시되지 아니한 사항에 대해서는 전기통신기본법, 전기통신사업법, &quot;정보통신망법&quot; 기타 관련 법령의 규정에 따릅니다.<br><br>제2장 서비스 이용계약의 체결<br><br>제5조(“서비스” 이용계약의 성립)<br>① 이용계약은 &quot;회원&quot;이 되고자 하는 자(이하 &quot;가입신청자&quot;)가 약관의 내용에 대하여 동의를 한 다음 회원가입신청을 하고 &quot;본포럼&quot;가 이러한 신청에 대하여 승낙함으로써 체결됩니다.<br>② &quot;본포럼&quot;는 &quot;가입신청자&quot;의 신청에 대하여 &quot;서비스&quot; 이용을 승낙함을 원칙으로 합니다. 다만, &quot;본포럼&quot;는 다음 각호에 해당하는 신청에 대하여는 승낙을 하지 않거나 사후에 이용계약을 해지할 수 있습니다.<br> 가. 본인의 실명으로 신청하지 않았을 때<br> 나. 다른 사람의 명의를 사용하여 신청하였을 때<br> 다. 신청서의 내용을 허위로 기재하였을 때<br> 라. 사회의 안녕질서 또는 미풍양속을 저해할 목적으로 신청하였을 때<br> 마. 기타 본포럼이 정한 이용신청 요건이 미비 되었을 때<br>③ 제1항에 따른 신청에 있어 &quot;본포럼&quot;는 &quot;회원&quot;에 따라 전문기관을 통한 실명확인 및 본인인증을 요청할 수 있습니다.<br>④ 제2항에 따라 회원가입신청의 승낙을 하지 아니하거나 유보한 경우, &quot;본포럼&quot;는 원칙적으로 이를 “가입신청자”에게 알리도록 합니다.<br>⑤ 이용계약의 성립 시기는 &quot;본포럼&quot;가 가입 완료를 신청절차 상에서 표시한 시점으로 합니다.<br><br>제6조(이용 신청의 승낙과 제한)<br>① “본포럼”는 제5조의 규정에 의한 이용 신청 고객에 대하여 업무 수행상 또는 기술상 지장이 없는 경우에 원칙적으로 접수 순서에 따라 “서비스” 이용을 승낙합니다.<br>② “본포럼”는 아래 사항에 해당하는 경우에 대해서 승낙하지 아니합니다.<br> 가. “가입신청자”가 이 약관에 의하여 이전에 회원자격을 상실한 적이 있는 경우, 단 &quot;본포럼&quot;의 “회원” 재가입 승낙을 얻은 경우에는 예외로 합니다.<br> 나. 실명이 아니거나 타인의 명의를 이용한 경우<br> 다. 허위의 정보를 기재하거나, &quot;본포럼&quot;가 제시하는 내용을 기재하지 않은 경우<br> 라. 14세 미만 아동이 법정대리인(부모 등)의 동의를 얻지 아니한 경우<br> 마. 이용자의 귀책사유로 인하여 승인이 불가능하거나 기타 규정한 제반 사항을 위반하며 신청하는 경우<br><br>제7조(회원정보의 변경)<br>① &quot;회원&quot;은 개인정보관리화면을 통하여 언제든지 본인의 개인정보를 열람하고 수정할 수 있습니다.<br>② &quot;회원&quot;은 회원가입신청 시 기재한 사항이 변경되었을 경우 온라인으로 수정을 하거나 전자우편 기타 방법으로 &quot;본포럼&quot;에 대하여 그 변경사항을 알려야 합니다.<br>③ 제2항의 변경사항을 &quot;본포럼&quot;에 알리지 않아 발생한 불이익에 대하여 &quot;본포럼&quot;는 책임지지 않습니다.<br>제8조(개인 정보의 보호)<br>① “본포럼”는 &quot;정보통신망법&quot; 등 관계 법령에 따라 회원가입 신청시 제공받은 개인 정보, 추후에 추가로 제공받는 개인 정보를 보호합니다.<br>② “본포럼”의 개인정보 보호책임자를 비롯한 개인정보보호에 관한 기타 사항은 별도로 정한 &quot;개인정보처리방침&quot;에 기재하여 공지합니다.<br><br>제9조(“아이디” 및 “비밀번호”의 관리에 대한 의무)<br>① &quot;회원&quot;의 &quot;아이디&quot;와 &quot;비밀번호&quot;에 관한 관리책임은 &quot;회원&quot;에게 있으며, 이를 제3자가 이용하도록 하여서는 안됩니다.<br>② &quot;본포럼&quot;는 &quot;회원&quot;의 &quot;아이디&quot;가 개인 정보 유출 우려가 있거나, 사회의 질서 또는 미풍양속에 어긋나거나 &quot;본포럼&quot; 및 &quot;본포럼&quot;의 운영자로 오인할 우려가 있는 경우, 해당 &quot;아이디&quot;의 이용을 제한할 수 있습니다.<br>③ &quot;회원&quot;은 &quot;아이디&quot; 및 &quot;비밀번호&quot;가 도용되거나 제3자가 사용하고 있음을 인지한 경우에는 이를 즉시 &quot;본포럼&quot;에 통지하고 &quot;본포럼&quot;의 안내에 따라야 합니다.<br>④ 제3항의 경우에 해당 &quot;회원&quot;이 &quot;본포럼&quot;에 그 사실을 통지하지 않거나, 통지한 경우에도 &quot;본포럼&quot;의 안내에 따르지 않아 발생한 불이익에 대하여 &quot;본포럼&quot;는 책임지지 않습니다.<br><br>제10조(“회원”에 대한 통지)<br>① &quot;본포럼&quot;가 &quot;회원&quot;에 대한 통지를 하는 경우 이 약관에 별도 규정이 없는 한 “서비스” 내 전자우편 주소 등으로 할 수 있습니다.<br>② &quot;본포럼&quot;는 &quot;회원&quot; 전체에 대한 통지의 경우 7일 이상 &quot;본포럼&quot;의 게시판에 게시함으로써 제1항의 통지에 갈음할 수 있습니다.<br><br>제3장 계약 당사자의 의무<br><br>제11조(“본포럼”의 의무)<br>① &quot;본포럼&quot;는 관련법과 이 약관이 금지하거나 미풍양속에 반하는 행위를 하지 않으며, “회원”이 희망한 “서비스” 제공 개시일에 특별한 사정이 없는 한 서비스를 이용할 수 있도록 최선을 다하여 노력합니다.<br>② “본포럼”는 계속적이고 안정적인 서비스의 제공을 위하여 설비에 장애가 생길 때에는 부득이한 사유가 없는 한 지체없이 이를 수리 또는 복구해야 합니다.<br>③ “본포럼”는 개인정보 보호를 위해 개인정보보호정책을 공시하고 준수합니다.<br>④ “본포럼”는 “회원”으로부터 제기되는 의견이나 불만이 정당하다고 객관적으로 인정할 경우에는 적절한 절차를 거쳐 이를 처리하여야 합니다. 다만, 즉시 처리가 곤란한 경우는 “회원”에게 그 사유와 처리 일정을 통보하여야 합니다.<br><br>제12조(“회원”의 의무)<br>① 인터넷회원은 해당메뉴를 이용함에 있어 다음 각 호의 행위를 하여서는 안됩니다.<br> 가. 타인의 “서비스” 아이디 및 비밀번호를 도용하는 행위<br> 나. 타인의 지적재산권을 침해하는 행위<br> 다. 타인의 명예를 훼손하거나 사생활을 침해하는 행위<br> 라. 게시판 등에서 욕설, 비방 또는 음란, 폭력적인 내용의 표현을 하는 행위<br> 마. 과실 또는 고의로 허위의 정보를 공개 또는 유포하는 행위<br> 바. 다량의 정보를 전송하거나 동일한 또는 유사한 내용의 정보를 반복적으로 게시하여 “서비스”의 안정적인 운영을 방해하는 행위<br> 사. 광고성 정보를 수신자의 의사에 반하여 게시판에 게시하여 다른 “회원”의 “서비스” 이용을 방해하는 행위<br> 아. 정보통신설비의 오작동이나 정보 등의 파괴를 유발하는 컴퓨터 바이러스 등을 유포하는 행위<br> 자. “본포럼”의 “서비스”를 이용하여 얻은 정보를 본포럼의 사전 승낙 없이 복제 또는 유통시키거나 상업적으로 이용하는 행위<br> 차. “본포럼”의 정상적인 경영 또는 업무를 방해하거나 “서비스”의 운영을 방해하는 행위<br> 카. 불법선거운동을 하는 행위<br> 타. 기타 미풍양속을 해하거나 관련법령 및 이 약관을 포함하여 “본포럼”가 정한 이용 조건에 위반하는 행위<br><br>제4장 서비스의 제공<br><br>제13조(“서비스” 이용 시간)<br>① “서비스” 이용은 “본포럼”의 업무상 또는 기술상 특별한 지장이 없는 한 연중무휴, 1일 24시간 운영을 원칙으로 합니다. 단, “본포럼”는 시스템 정기점검, 증설 및 교체를 위해 “본포럼”가 정한 날이나 시간에 서비스를 일시 중단할 수 있으며, 예정되어 있는 작업으로 인한 서비스 일시 중단은 “서비스”의 페이지를 통해 사전에 공지합니다.<br>② “본포럼”는 긴급한 시스템 점검, 증설 및 교체 등 부득이한 사유로 인하여 예고 없이 일시적으로 “서비스”를 중단할 수 있으며, 새로운 서비스로의 교체 등 “본포럼”가 적절하다고 판단하는 사유에 의하여 현재 제공되는 “서비스”를 완전히 중단할 수 있습니다.<br>③ “본포럼”는 국가비상사태, 정전, 서비스 설비의 장애 또는 “본포럼” 이용의 폭주 등으로 정상적인 서비스 제공이 불가능할 경우, “서비스”의 전부 또는 일부를 제한하거나 중지할 수 있습니다. 다만 이 경우 그 사유 및 기간 등을 “회원”에게 사전 또는 사후에 공지합니다.<br>④ “본포럼”는 “서비스”를 특정범위로 분할하여 각 범위별로 이용가능시간을 별도로 지정할 수 있습니다. 다만 이 경우 그 내용을 공지합니다.<br><br>제14조(“서비스”의 변경)<br>① &quot;본포럼&quot;는 상당한 이유가 있는 경우에 운영상, 기술상의 필요에 따라 제공하고 있는 전부 또는 일부 &quot;서비스&quot;를 변경할 수 있습니다.<br>② &quot;서비스&quot;의 내용, 이용방법, 이용시간에 대하여 변경이 있는 경우에는 변경사유, 변경될 서비스의 내용 및 제공일자 등은 그 변경 전에 해당 서비스 초기화면에 게시하여야 합니다.<br>③ &quot;본포럼&quot;에서 제공되는 “서비스”의 일부 또는 전부를 본포럼의 정책 및 운영의 필요상 수정, 중단, 변경할 수 있으며, 이에 대하여 관련법에 특별한 규정이 없는 한 &quot;회원&quot;에게 별도의 보상을 하지 않습니다.<br><br>제15조(정보의 제공)<br>① “본포럼”는 “회원”에게 “서비스” 이용에 필요가 있다고 인정되는 각종 정보에 대해서 “서비스” 화면이나 전자 우편 또는 서신 우편 등의 방법으로 “회원”에게 제공할 수 있습니다. 다만, &quot;회원&quot;은 관련법에 따른 회원문의 사항 등에 대한 답변 등을 제외하고는 언제든지 전자우편에 대해서 수신 거절을 할 수 있습니다.<br>② “본포럼”는 “서비스” 개선 및 “회원” 대상의 “서비스” 소개 등의 목적으로 “회원”의 동의 하에 추가적인 개인 정보를 요구할 수 있습니다.<br><br>제16조(권리의 귀속)<br>① &quot;서비스&quot;에 대한 저작권 및 지적재산권은 &quot;본포럼&quot;에 귀속됩니다. 단, &quot;회원&quot;의 &quot;게시물&quot; 및 제휴계약에 따라 제공된 저작물 등은 제외합니다.<br>② &quot;본포럼&quot;는 “서비스”와 관련하여 &quot;회원&quot;에게 &quot;본포럼&quot;가 정한 이용 조건에 따라 &#39;계정(아이디)&#39;, 콘텐츠, 등을 이용할 수 있는 이용권한만을 부여하며, &quot;회원&quot;은 이를 양도, 판매, 담보제공 등의 처분행위를 할 수 없습니다.<br><br>제17조(“게시물”의 저작권)<br>① &quot;회원&quot;이 &quot;서비스&quot; 내에 게시한 &quot;게시물&quot;의 저작권은 해당 게시물의 저작자에게 귀속됩니다.<br>② “본포럼”는 저작권법 규정을 준수하며, &quot;회원&quot;은 &quot;서비스&quot; 내 관리기능을 통해 해당 게시물에 대해 삭제, 검색결과 제외, 비공개 등의 조치를 취할 수 있습니다.<br>③ &quot;본포럼&quot;는 제2항 이외의 방법으로 &quot;회원&quot;의 &quot;게시물&quot;을 이용하고자 하는 경우에는 전화, 팩스, 전자우편 등을 통해 사전에 &quot;회원&quot;의 동의를 얻어야 합니다.<br><br>제18조(“게시물”의 관리)<br>① &quot;회원&quot;의 &quot;게시물&quot;이 &quot;정보통신망법&quot; 및 &quot;저작권법&quot;등 관련법에 위반되는 내용을 포함하는 경우, 권리자는 관련법이 정한 절차에 따라 해당 &quot;게시물&quot;의 게시중단 및 삭제 등을 요청할 수 있으며, &quot;본포럼&quot;는 관련법에 따라 조치를 취하여야 합니다.<br>② &quot;본포럼&quot;는 전항에 따른 권리자의 요청이 없는 경우라도 권리침해가 인정될 만한 사유가 있거나 기타 본포럼 정책 및 관련법에 위반되는 경우에는 관련법에 따라 해당 &quot;게시물&quot;에 대해 게시중단 및 삭제조치 등을 취할 수 있습니다.<br><br>③ 본 조에 따른 세부절차는 &quot;정보통신망법&quot; 및 &quot;저작권법&quot; 등 &quot;본포럼&quot;가 정한 게시중단요청에 따릅니다.<br><br>제19조(계약해제 및 해지)<br>① &quot;회원&quot;은 언제든지 서비스 초기화면의 고객센터 또는 내 정보 관리 메뉴 등을 통하여 이용계약 해지 신청을 할 수 있으며, &quot;본포럼&quot;는 관련법 등이 정하는 바에 따라 이를 처리하여야 합니다.<br>② &quot;회원&quot;이 계약을 해지할 경우, 관련법 및 개인정보취급방법에 따라 &quot;본포럼&quot;가 회원정보를 보유하는 경우를 제외하고는 해지 즉시 &quot;회원&quot;의 모든 데이터는 소멸됩니다.<br>③ &quot;회원&quot;이 계약을 해지하는 경우, 게시판에 등록된 &quot;게시물&quot; 등은 삭제되지 않으니 사전에 삭제 후 탈퇴하여야 합니다.<br><br>제5장 분쟁 조정 및 기타 사항<br><br>제20조(책임제한)<br>① &quot;본포럼&quot;는 천재지변 또는 이에 준하는 불가항력으로 인하여 &quot;서비스&quot;를 제공할 수 없는 경우에는 &quot;서비스&quot; 제공에 관한 책임이 면제됩니다.<br>② &quot;본포럼&quot;는 &quot;회원&quot;의 귀책사유로 인한 &quot;서비스&quot; 이용의 장애에 대하여는 책임을 지지 않습니다.<br>③ &quot;본포럼&quot;는 &quot;회원&quot;이 &quot;서비스&quot;와 관련하여 게재한 정보, 자료, 사실의 신뢰도, 정확성 등의 내용에 관하여는 책임을 지지 않습니다.<br>④ &quot;본포럼&quot;는 무료로 제공되는 서비스 이용과 관련하여 관련법에 특별한 규정이 없는 한 책임을 지지 않습니다.<br>⑤ “본포럼”가 개별서비스 제공자와 제휴 협정을 맺고 “회원”에게 개별서비스를 제공함에 있어 “회원”이 개별서비스 이용약관에 동의를 한 뒤 개별서비스 제공자의 귀책사유로 인해 손해가 발생할 경우 관련 손해에 대해서는 개별서비스 제공자가 책임을 집니다.<br><br>제21조(재판권 및 준거법)<br>① &quot;본포럼&quot;와 &quot;회원&quot; 간 제기된 소송은 대한민국법을 준거법으로 합니다.<br>② &quot;본포럼&quot;와 &quot;회원&quot; 간 발생한 분쟁에 관한 소송은 서울중앙지방법원을 관할법원으로 합니다.<br><br>부 칙<br>(시행일) 이 약관은 2026년 4월 9일부터 시행합니다.</section>','[]',25,'2026-11-10 06:02:28');
INSERT INTO "pages" ("path","title","html","images","sort_order","updated_at") VALUES ('/privacy','개인정보처리방침','<section class="content-block"><h2>새 홈페이지 문의 접수 개인정보 안내</h2><p>처리자: 사단법인 ESG정원정책포럼</p><p>문의: esg.gardenpolicy@gmail.com</p><h3>수집 항목 및 목적</h3><p>문의 유형, 이름, 이메일, 기관명(선택), 제목, 문의내용을 협력·정책제안·회원가입·후원 문의에 응답하기 위해 수집합니다. 민감정보와 고유식별정보는 입력하지 마세요. 문의 접수는 회원등록·납부 완료를 뜻하지 않습니다.</p><h3>보관 및 삭제</h3><p>접수일로부터 최대 1년 보관 후 자동 삭제합니다. 관리자에게 조기 삭제를 요청할 수 있습니다. 개인정보는 공개 게시판에 노출하지 않습니다.</p><h3>처리 환경</h3><p>서비스 호스팅 및 데이터 저장은 Cloudflare Workers와 D1을 이용합니다. 서비스 제공 과정에서 Cloudflare의 글로벌 인프라에서 데이터가 처리될 수 있습니다. 외부 전송 이메일·결제·광고 추적 기능은 사용하지 않습니다. 보안 유지를 위한 요청 횟수 정보는 단기간 보관합니다. 관리자 로그인 쿠키는 8시간 후 만료됩니다.</p><h3>동의와 권리</h3><p>수집·이용 동의를 거부할 수 있으며 이 경우 온라인 문의 접수가 제한됩니다. 열람·정정·삭제 요청은 사무국 이메일로 보내실 수 있습니다.</p></section><details><summary>개편 전 사이트 개인정보처리방침 원문 보존</summary><p>아래는 기존 사이트 원문입니다. 회사명 등 미완성 표기는 원본에 있던 내용이며, 새 문의 접수에 관한 내용은 위 안내를 확인해 주세요.</p>개인정보처리방침<br>	<br>		<br>		닫기<br>	<br><br><br>	회사명(이하 ‘회사’라 한다)는 개인정보 보호법 제30조에 따라 정보 주체의 개인정보를 보호하고 이와 관련한 고충을 신속하고 원활하게 처리할 수 있도록 하기 위하여 다음과 같이 개인정보 처리지침을 수립, 공개합니다.<br><br>제1조 (개인정보의 처리목적)<br>회사는 다음의 목적을 위하여 개인정보를 처리합니다. 처리하고 있는 개인정보는 다음의 목적 이외의 용도로는 이용되지 않으며, 이용 목적이 변경되는 경우에는 개인정보보호법 제18조에 따라 별도의 동의를 받는 등 필요한 조치를 이행할 예정입니다.<br><br>1. 홈페이지 회원 가입 및 관리<br>회원 가입 의사 확인, 회원제 서비스 제공에 따른 본인 식별․인증, 회원자격 유지․관리, 제한적 본인확인제 시행에 따른 본인확인, 서비스 부정 이용 방지, 만 14세 미만 아동의 개인정보처리 시 법정대리인의 동의 여부 확인, 각종 고지․통지, 고충 처리 등을 목적으로 개인정보를 처리합니다.<br><br>2. 재화 또는 서비스 제공<br>물품 배송, 서비스 제공, 계약서 및 청구서 발송, 콘텐츠 제공, 맞춤서비스 제공, 본인인증, 연령인증, 요금 결제 및 정산, 채권추심 등을 목적으로 개인정보를 처리합니다.<br><br>3. 고충 처리<br>민원인의 신원 확인, 민원사항 확인, 사실조사를 위한 연락․통지, 처리 결과 통보 등의 목적으로 개인정보를 처리합니다.<br><br>제2조 (개인정보의 처리 및 보유기간)<br>① 회사는 법령에 따른 개인정보 보유, 이용 기간 또는 정보주체로부터 개인정보를 수집 시에 동의 받은 개인정보 보유, 이용 기간 내에서 개인정보를 처리, 보유합니다.<br>② 각각의 개인정보 처리 및 보유 기간은 다음과 같습니다.<br><br>1. 홈페이지 회원 가입 및 관리 : 사업자/단체 홈페이지 탈퇴 시까지<br>다만, 다음의 사유에 해당하는 경우에는 해당 사유 종료 시까지<br>1) 관계 법령 위반에 따른 수사, 조사 등이 진행 중인 경우에는 해당 수사, 조사 종료 시까지<br>2) 홈페이지 이용에 따른 채권 및 채무관계 잔존 시에는 해당 채권, 채무 관계 정산 시까지<br><br><br>2. 재화 또는 서비스 제공 : 재화․서비스 공급완료 및 요금결제․정산 완료 시까지<br>다만, 다음의 사유에 해당하는 경우에는 해당 기간 종료 시까지<br>1) 「전자상거래 등에서의 소비자 보호에 관한 법률」에 따른 표시․광고, 계약내용 및 이행 등 거래에 관한 기록<br>- 표시․광고에 관한 기록 : 6월<br>- 계약 또는 청약 철회, 대금결제, 재화 등의 공급기록 : 5년<br>- 소비자 불만 또는 분쟁 처리에 관한 기록 : 3년<br>2) 「통신비밀보호법」 제41조에 따른 통신사실확인자료 보관<br>- 가입자 전기통신일시, 개시․종료 시간, 상대방 가입자 번호, 사용도수, 발신기지국 위치추적자료 : 1년<br>- 컴퓨터 통신, 인터넷 로그 기록자료, 접속지 추적자료 : 3개월<br><br><br>제3조 (개인정보의 제3자 제공)<br>① 회사는 정보주체의 개인정보를 제1조(개인정보의 처리목적)에서 명시한 범위 내에서만 처리하며, 정보주체의 동의, 법률의 특별한 규정 등 개인정보 보호법 제17조 및 제 18조에 해당하는 경우에만 개인정보를 제3자에게 제공하고 그 외에는 정보주체의 개인정보를 제3자에게 제공하지 않습니다.<br>② 회사는 원활한 서비스 제공을 위해 다음의 경우 개인정보보호법 제17조 제1항 제1호에 따라 정보주체의 동의를 얻어 필요 최소한의 범위로만 개인정보를 제3자에게 제공할 수 있습니다.<br>- 개인정보를 제공받는 자 : &lt;예) (주) OOO 카드&gt;<br>- 제공받는 자의 개인정보 이용목적 : &lt;예) 이벤트 공동개최 등 업무제휴 및 제휴 신용카드 발급&gt;<br>- 제공하는 개인정보 항목 : &lt;예) 성명, 주소, 전화번호, 이메일주소, 카드결제계좌정보&gt;<br>- 제공받는 자의 보유, 이용기간 : &lt;예) 신용카드 발급계약에 따른 거래기간동안&gt;<br><br><br>제4조(개인정보처리의 위탁)<br>① 회사는 원활한 개인정보 업무처리를 위하여 다음과 같이 개인정보 처리업무를 위탁하고 있습니다.<br>- 위탁업무 내용<br>- 위탁받는 자 (수탁자) : (주)아임웹<br>- 위탁하는 업무의 내용 : 쇼핑몰 호스팅 서비스의 시스템 제공, 모바일 앱 서비스, 마케팅 서비스 및 부가, 제휴서비스 제공 및 알림톡, 친구톡, 문자메시지 발송대행 서비스, 판매 채널 주문 연동 서비스 등<br>- 위탁받는 자 (수탁자) : OOO PG<br>- 위탁하는 업무의 내용 : 결제 및 에스크로 업무<br>- 위탁받는 자 (수탁자) : OOO 택배<br>- 위탁하는 업무의 내용 : 상품 배송 업무<br>- 위탁받는 자 (수탁자) : OOO 고객센터<br>- 위탁하는 업무의 내용 : 고객상담 업무<br>- 위탁받는 자 (수탁자) : OOO<br>- 위탁하는 업무의 내용 : 본인확인 업무<br>- **재위탁사**<br>- **재위탁받는 자(수탁자) : (주)아임웹 → 인포빕(유)**<br>- **위탁하는 업무의 내용 : 문자메시지 발송, 카카오톡 알림톡(정보성 메시지) 발송 업무**<br>- **재위탁받는 자(수탁자) : (주)아임웹 → (주)루나소프트**<br>- **위탁하는 업무의 내용 : 문자메시지 발송, 카카오톡 알림톡(정보성 메시지) 및 친구톡 발송 업무**<br>② 회사는 위탁계약 체결 시 개인정보 보호법 제25조에 따라 위탁업무 수행목적 외 개인정보 처리금지, 기술적․관리적 보호조치, 재위탁 제한, 수탁자에 대한 관리․감독, 손해배상 등 책임에 관한 사항을 계약서 등 문서에 명시하고, 수탁자가 개인정보를 안전하게 처리하는지를 감독하고 있습니다.<br>③ 위탁업무의 내용이나 수탁자가 변경될 경우에는 지체없이 본 개인정보 처리방침을 통하여 공개하도록 하겠습니다.<br><br>제5조(정보주체 및 법정대리인의 권리와 그 행사 방법)<br><br>① 정보주체는 회사에 대해 언제든지 다음 각 호의 개인정보 보호 관련 권리를 행사할 수 있습니다.<br>1. 개인정보 열람 요구<br>2. 오류 등이 있을 경우 정정 요구<br>3. 삭제요구<br>4. 처리정지 요구<br>② 제1항에 따른 권리 행사는 회사에 대해 서면, 전화, 전자우편, 모사전송(FAX) 등을 통하여 하실 수 있으며 회사는 이에 대해 지체없이 조치하겠습니다.<br>③ 정보주체가 개인정보의 오류 등에 대한 정정 또는 삭제를 요구한 경우에는 회사는 정정 또는 삭제를 완료할 때까지 당해 개인정보를 이용하거나 제공하지 않습니다.<br>④ 제1항에 따른 권리 행사는 정보주체의 법정대리인이나 위임을 받은 자 등 대리인을 통하여 하실 수 있습니다. 이 경우 개인정보 보호법 시행규칙 별지 제11호 서식에 따른 위임장을 제출하셔야 합니다.<br>⑤ 정보주체는 개인정보 보호법 등 관계 법령을 위반하여 회사가 처리하고 있는 정보주체 본인이나 타인의 개인정보 및 사생활을 침해하여서는 아니 됩니다.<br><br><br>제6조(처리하는 개인정보 항목)<br>회사는 다음의 개인정보 항목을 처리하고 있습니다.<br><br>1. 홈페이지 회원 가입 및 관리<br>필수항목 : &lt;예) 성명, 생년월일, 아이디, 비밀번호, 주소, 전화번호, 성별, 이메일주소, 아이핀번호&gt;<br>선택항목 : &lt;예) 결혼 여부, 관심 분야&gt;<br><br>2. 재화 또는 서비스 제공<br>필수항목 : &lt;예) 성명, 생년월일, 아이디, 비밀번호, 주소, 전화번호, 이메일주소, 아이핀번호, 신용카드번호, 은행계좌정보 등 결제정보&gt;<br>선택항목 : &lt;관심분야, 과거 구매내역&gt;<br><br>제7조(개인정보의 파기)<br>① 회사는 개인정보 보유 기간의 경과, 처리목적 달성 등 개인정보가 불필요하게 되었을 때에는 지체없이 해당 개인정보를 파기합니다.<br>② 정보주체로부터 동의받은 개인정보 보유 기간이 경과하거나 처리목적이 달성되었음에도 불구하고 다른 법령에 따라 개인정보를 계속 보존하여야 하는 경우에는, 해당 개인정보를 별도의 데이터베이스(DB)로 옮기거나 보관장소를 달리하여 보존합니다.<br>③ 개인정보 파기의 절차 및 방법은 다음과 같습니다.<br>1. 파기 절차<br>회사는 파기 사유가 발생한 개인정보를 선정하고, 회사의 개인정보 보호책임자의 승인을 받아 개인정보를 파기합니다.<br>2. 파기 방법<br>회사는 전자적 파일 형태로 기록․저장된 개인정보는 기록을 재생할 수 없도록 파기하며, 종이 문서에 기록․저장된 개인정보는 분쇄기로 분쇄하거나 소각하여 파기합니다.<br><br>제8조(개인정보의 안전성 확보조치)<br>회사는 개인정보의 안전성 확보를 위해 다음과 같은 조치를 하고 있습니다.<br>1. 관리적 조치 : 내부관리계획 수립 및 시행, 정기적 직원 교육 등<br>2. 기술적 조치 : 개인정보처리시스템 등의 접근 권한 관리, 접근통제시스템 설치, 고유 식별정보<br>등의 암호화, 보안프로그램 설치<br>3. 물리적 조치 : 전산실, 자료보관실 등의 접근통제<br><br>제9조(개인정보 자동 수집 장치의 설치∙운영 및 거부에 관한 사항)<br>① 회사는 이용자에게 개별적인 맞춤 서비스를 제공하기 위해 이용정보를 저장하고 수시로 불러오는 ‘쿠키(cookie)’를 사용합니다.<br>② 쿠키는 웹사이트를 운영하는데 이용되는 서버(http)가 이용자의 컴퓨터 브라우저에 보내는 소량의 정보이며 이용자들의 PC 또는 모바일에 저장됩니다.<br>③ 정보주체는 웹 브라우저 옵션 설정을 통해 쿠키 허용, 차단 등의 설정을 할 수 있습니다. 다만, 쿠키 저장을 거부할 경우 맞춤형 서비스 이용에 어려움이 발생할 수 있습니다.<br><br>▶ 웹 브라우저에서 쿠키 허용/차단<br>- 크롬(Chrome) : 웹 브라우저 설정 &gt; 개인정보 보호 및 보안 &gt; 인터넷 사용기록 삭제<br>- 엣지(Edge) : 웹 브라우저 설정 &gt; 쿠키 및 사이트 권한 &gt; 쿠키 및 사이트 데이터 관리 및 삭제<br><br>▶ 모바일 브라우저에서 쿠키 허용/차단<br>- 크롬(Chrome) : 모바일 브라우저 설정 &gt; 개인정보 보호 및 보안 &gt; 인터넷 사용기록 삭제<br>- 사파리(Safari) : 모바일 기기 설정 &gt; 사파리(Safari) &gt; 고급 &gt; 모든 쿠키 차단<br>- 삼성 인터넷 : 모바일 브라우저 설정 &gt; 인터넷 사용 기록 &gt; 인터넷 사용 기록 삭제<br><br>④ 회사는 서비스 이용과정에서 사용자가 방문한 각 서비스와 웹 사이트들에 대한 방문 및 이용형태, 인기 검색어, 보안접속 여부 등을  파악하여 이용자에게 최적화된 정보 제공을 위해 수집・이용하고 있습니다.<br><br><br>제10조(개인정보 보호책임자)<br>① 회사는 개인정보 처리에 관한 업무를 총괄해서 책임지고, 개인정보 처리와 관련한 정보주체의 불만 처리 및 피해구제 등을 위하여 아래와 같이 개인정보 보호책임자를 지정하고 있습니다.<br><br>▶ 개인정보 보호책임자<br>성명 : OOO<br>직책 : OOO<br>연락처 : &lt;전화번호&gt;, &lt;이메일&gt;, &lt;팩스번호&gt;<br>※ 개인정보 보호 담당부서로 연결됩니다.<br><br>▶ 개인정보 보호 담당부서<br>부서명 : OOO 팀<br>연락처 : &lt;전화번호&gt;, &lt;이메일&gt;, &lt;팩스번호&gt;<br><br>② 정보주체께서는 회사의 서비스(또는 사업)을 이용하시면서 발생한 모든 개인정보 보호 관련 문의, 불만 처리, 피해구제 등에 관한 사항을 개인정보 보호책임자 및 담당부서로 문의하실 수 있습니다. 회사는 정보주체의 문의에 대해 지체없이 답변 및 처리해드릴 것입니다.<br><br><br>제11조(개인정보 열람청구)<br>정보주체는 개인정보 보호법 제35조에 따른 개인정보의 열람 청구를 아래의 부서에 할 수 있습니다. 회사는 정보주체의 개인정보 열람 청구가 신속하게 처리되도록 노력하겠습니다.<br><br>▶ 개인정보 열람청구 접수․처리 부서<br>부서명 : OOO<br>연락처 : &lt;전화번호&gt;, &lt;이메일&gt;, &lt;팩스번호&gt;<br><br>제12조(권익침해 구제 방법)<br>정보주체는 아래의 기관에 대해 개인정보 침해에 대한 피해구제, 상담 등을 문의하실 수 있습니다.<br>1. 개인정보 분쟁조정위원회 : (국번없이) 1833-6972 (www.kopico.go.kr)<br>2. 개인정보침해신고센터 : (국번없이) 118 (privacy.kisa.or.kr)<br>3. 대검찰청 : (국번없이) 1301 (www.spo.go.kr)<br>4. 경찰청 : (국번없이) 182 (ecrm.police.go.kr/minwon/main)<br><br><br>제13조(개인정보 처리방침 시행 및 변경)<br>이 개인정보 처리방침은 20XX. X. X. 부터 적용됩니다.</details>','[]',26,'2026-11-10 06:02:28');
INSERT INTO "posts" ("id","category","title","body","created_at","updated_at","attachment_url","image_url","source_url","published") VALUES ('171400121','notice','ESG정원정책포럼 홈페이지를 개편했어요~!','<div class="margin-top-xxl _comment_body_m202604220eff40dcb8c74"><p>안녕하세요.<br>ESG정원정책포럼입니다.</p><p>포럼의 새로운 방향과 활동을 보다 깊이 있게 담아내기 위해 홈페이지를 새롭게 개편하였습니다.</p><p>이번 개편은 단순한 디자인 변화가 아니라,<br>정원과 ESG를 연결하는 정책·연구·교육·실천 플랫폼으로서의 정체성을 보다 선명하게 전달하고,<br>회원과 시민, 공공기관, 기업이 함께 연결될 수 있는 공간을 만들어가는 과정이었습니다.</p><p>새 홈페이지에서는<br>정원정책과 ESG 관련 정책·연구 자료, 사업 및 교육 프로그램, 국내외 사례와 다양한 소식을 보다 체계적으로 만나보실 수 있으며,<br>앞으로 뉴스클리핑과 아카이브, 회원 대상 콘텐츠도 순차적으로 확대해나갈 예정입니다.</p><p>기후위기와 지역소멸, 공동체 회복이라는 시대적 과제 속에서<br>정원이 단순한 공간을 넘어 사람과 도시, 자연과 미래를 연결하는 지속가능한 플랫폼이 될 수 있도록<br>저희 포럼도 한 걸음씩 더 깊이 나아가겠습니다.</p><p>새롭게 단장한 홈페이지에 많은 관심과 응원 부탁드립니다.</p><p>감사합니다.</p><p>ESG정원정책포럼 드림</p></div>
					<div class="file_area"></div>
				','2026-05-21','2026-11-10 06:02:28','','','https://esggardenpolicy50279.imweb.me/notice/?q=YToxOntzOjEyOiJrZXl3b3JkX3R5cGUiO3M6MzoiYWxsIjt9&bmode=view&idx=171400121&t=board',1);
