INSERT INTO "posts" ("id","category","title","body","created_at","updated_at","attachment_url","image_url","source_url","published") VALUES ('171400561','news','[Weekly] 5월 4주차 정원정책 뉴스','<div class="margin-top-xxl _comment_body_m202604220eff40dcb8c74"><p>2026.5.20 | 정원이 사회적 처방이 된다… 국립수목원, 태안서 「정원산책」 운영</p><p>국립수목원이 태안국제원예치유박람회에서 지역 주민의 몸과 마음 회복을 위한 사회적 처방형 정원치유 프로그램 「정원산책」을 운영하는데, 참가자들은 정원 산책, 식물 관찰, 명상 등을 통해 스트레스를 완화하고 정서적 회복을 경험할 수 있도록 구성되었다고 한다. 국립수목원은 박람회 이후에도 모델정원을 지역 주민의 지속 가능한 정원치유 거점으로 활용할 계획이라고 밝혔다.&nbsp;</p><p>기사 원문 바로가기 : https://www.forest.go.kr/kfsweb/cop/bbs/selectBoardList.do?bbsId=BBSMSTR_1036&amp;mn=NKFS_04_02_01</p></div>
					<div class="file_area"></div>
				','2026-05-21','2026-11-10 06:02:28','','','https://esggardenpolicy50279.imweb.me/news/?q=YToxOntzOjEyOiJrZXl3b3JkX3R5cGUiO3M6MzoiYWxsIjt9&bmode=view&idx=171400561&t=board',1);
INSERT INTO "settings" ("key","value") VALUES ('analytics_started_at','2026-11-10T14:51:29.194Z');
CREATE INDEX analytics_events_day ON analytics_events(day,at);
CREATE INDEX analytics_events_recent ON analytics_events(at DESC);
CREATE INDEX analytics_sessions_active ON analytics_sessions(last_seen DESC);
CREATE INDEX inquiries_created_at ON inquiries(created_at DESC);
CREATE INDEX inquiries_status ON inquiries(status,created_at);
CREATE INDEX posts_category ON posts(category,published,created_at);
CREATE TRIGGER analytics_on_view AFTER INSERT ON analytics_events BEGIN
 INSERT INTO analytics_sessions(day,sid,device,referrer,first_seen,last_seen,views)
 VALUES(NEW.day,NEW.sid,NEW.device,NEW.referrer,NEW.at,NEW.at,1)
 ON CONFLICT(day,sid) DO UPDATE SET last_seen=MAX(last_seen,excluded.last_seen),views=views+1;
 INSERT INTO analytics_daily(day,views,sessions)
 VALUES(NEW.day,1,(SELECT CASE WHEN views=1 THEN 1 ELSE 0 END FROM analytics_sessions WHERE day=NEW.day AND sid=NEW.sid))
 ON CONFLICT(day) DO UPDATE SET views=views+1,sessions=sessions+excluded.sessions;
 INSERT INTO analytics_page_daily(day,path,views) VALUES(NEW.day,NEW.path,1)
 ON CONFLICT(day,path) DO UPDATE SET views=views+1;
 INSERT INTO analytics_hourly(day,hour,views) VALUES(NEW.day,CAST(strftime('%H',NEW.at,'unixepoch','+9 hours') AS INTEGER),1)
 ON CONFLICT(day,hour) DO UPDATE SET views=views+1;
 INSERT INTO analytics_devices_daily(day,device,views,sessions)
 VALUES(NEW.day,(SELECT device FROM analytics_sessions WHERE day=NEW.day AND sid=NEW.sid),1,(SELECT CASE WHEN views=1 THEN 1 ELSE 0 END FROM analytics_sessions WHERE day=NEW.day AND sid=NEW.sid))
 ON CONFLICT(day,device) DO UPDATE SET views=views+1,sessions=sessions+excluded.sessions;
 INSERT INTO analytics_referrers_daily(day,host,views,sessions)
 VALUES(NEW.day,(SELECT referrer FROM analytics_sessions WHERE day=NEW.day AND sid=NEW.sid),1,(SELECT CASE WHEN views=1 THEN 1 ELSE 0 END FROM analytics_sessions WHERE day=NEW.day AND sid=NEW.sid))
 ON CONFLICT(day,host) DO UPDATE SET views=views+1,sessions=sessions+excluded.sessions;
END;
